using Brisa.Api;using Brisa.Api.Domain;using Brisa.Api.Rules;var builder=WebApplication.CreateBuilder(args);builder.Services.AddSignalR();builder.Services.AddSingleton<RollService>();var app=builder.Build();app.MapGet("/health",()=>Results.Ok(new {status="ok",system="Brisa e Lamentações"}));app.MapPost("/api/rolls",(RollRequest request,RollService rules)=>Results.Ok(rules.Resolve(request)));app.MapHub<SessionHub>("/hubs/session");app.Run();
